from abc import ABC
from datetime import datetime
from typing import List
from urllib.parse import urljoin
from playwright.sync_api import Page
from crawler.constants.constant import RAW_PATH_CONSTANTS
from crawler.crawler_instance.local_interface_model.leak.leak_extractor_interface import leak_extractor_interface
from crawler.crawler_instance.local_shared_model.data_model.entity_model import entity_model
from crawler.crawler_instance.local_shared_model.data_model.leak_model import leak_model
from crawler.crawler_instance.local_shared_model.rule_model import RuleModel, FetchProxy, FetchConfig, ThreatType
from crawler.crawler_services.redis_manager.redis_controller import redis_controller
from crawler.crawler_services.redis_manager.redis_enums import REDIS_COMMANDS, CUSTOM_SCRIPT_REDIS_KEYS
from crawler.crawler_services.shared.helper_method import helper_method


class _yzcpwxuhbkyjnyn4qsf4o5dkvu6m2fyo7dwizmnlutanlmzlos7pa6qd(leak_extractor_interface, ABC):
    _instance = None

    def __init__(self, callback=None):

        self.callback = callback
        self._card_data = []
        self._entity_data = []
        self.soup = None
        self._initialized = None
        self._redis_instance = redis_controller()
        self._is_crawled = False

    def init_callback(self, callback=None):

        self.callback = callback

    def __new__(cls, callback=None):

        if cls._instance is None:
            cls._instance = super(_yzcpwxuhbkyjnyn4qsf4o5dkvu6m2fyo7dwizmnlutanlmzlos7pa6qd, cls).__new__(cls)
            cls._instance._initialized = False
        return cls._instance

    @property
    def is_crawled(self) -> bool:
        return self._is_crawled

    @property
    def seed_url(self) -> str:
        return "http://yzcpwxuhbkyjnyn4qsf4o5dkvu6m2fyo7dwizmnlutanlmzlos7pa6qd.onion/"

    @property
    def developer_signature(self) -> str:
        return "Muhammad Marij Younas:"

    @property
    def base_url(self) -> str:
        return "http://yzcpwxuhbkyjnyn4qsf4o5dkvu6m2fyo7dwizmnlutanlmzlos7pa6qd.onion/"

    @property
    def rule_config(self) -> RuleModel:
        return RuleModel(m_fetch_proxy=FetchProxy.TOR, m_fetch_config=FetchConfig.PLAYRIGHT, m_threat_type= ThreatType.LEAK,m_resoource_block=False)

    @property
    def card_data(self) -> List[leak_model]:
        return self._card_data

    @property
    def entity_data(self) -> List[entity_model]:
        return self._entity_data

    def invoke_db(self, command: int, key: str, default_value, expiry: int = None):
        return self._redis_instance.invoke_trigger(command, [key + self.__class__.__name__, default_value, expiry])

    def contact_page(self) -> str:
        return "http://yzcpwxuhbkyjnyn4qsf4o5dkvu6m2fyo7dwizmnlutanlmzlos7pa6qd.onion/"

    def append_leak_data(self, leak: leak_model, entity: entity_model):

        self._card_data.append(leak)
        self._entity_data.append(entity)
        if self.callback:
            if self.callback():
                self._card_data.clear()
                self._entity_data.clear()

    def parse_leak_data(self, page: Page):

        links = page.eval_on_selector_all(
            ".news-content a",
            "els => els.map(e => e.getAttribute('href'))"
        )

        for link in links:
            full_url = link if link.startswith("http") else urljoin(self.base_url, link)
            page.goto(full_url)

            title = page.locator('h1[style*="margin-bottom: 5px;"]').inner_text() if page.locator(
                'h1[style*="margin-bottom: 5px;"]').count() else ""
            content = page.locator('p[style*="text-align: justify;"]').first.inner_text() if page.locator(
                'p[style*="text-align: justify;"]').count() else ""
            date = page.locator('h3[style*="margin-bottom: 25px;"]').inner_text() if page.locator(
                'h3[style*="margin-bottom: 25px;"]').count() else ""
            date_obj = datetime.strptime(date, "%Y-%m-%d").date()

            images = page.eval_on_selector_all(".top img", "els => els.map(e => e.getAttribute('src'))")
            image_links = [urljoin(self.base_url, img) for img in images if img]
            image_links_str = ", ".join(image_links)

            main_links = page.eval_on_selector_all(".main a", "els => els.map(e => e.getAttribute('href'))")
            main_links_full = [urljoin(self.base_url, link) for link in main_links if link]
            main_links_str = ", ".join(main_links_full)

            ref_html = helper_method.extract_refhtml(title, self.invoke_db, REDIS_COMMANDS, CUSTOM_SCRIPT_REDIS_KEYS,
                                                     RAW_PATH_CONSTANTS, page)

            m_content = (
                f"Title: {title}\n"
                f"Content: {content}\n"
                f"Date: {date}\n"
                f"Images: {image_links_str}\n"
                f"DumpLinks: {main_links_str}\n"
                f"PageURL: {full_url}\n"
            )

            card_data = leak_model(
                  m_ref_html=ref_html,
                  m_title=title,
                  m_url=page.url,
                  m_base_url=self.base_url,
                  m_content=m_content,
                  m_network=helper_method.get_network_type(self.base_url),
                  m_important_content=content.strip(),
                  m_screenshot=helper_method.get_screenshot_base64(page, title, self.base_url),
                  m_content_type=["leaks"],
                  m_logo_or_images=[image_links_str],
                  m_dumplink=[main_links_str],
                  m_leak_date=date_obj,
                 )

            entity_data = entity_model(
                    m_scrap_file=self.__class__.__name__,
                    m_team="NASIR SECUTRIY",
                  )

            self.append_leak_data(card_data, entity_data)


